import{_ as a,C as r,o,c as h,aj as d,E as c}from"./framework.js";const _=JSON.parse('{"title":"邮箱：撰写邮件 | Product / Mail | Documentation","description":"邮箱：撰写邮件 in Kooboo: 如果进入撰写页时没有可用发件地址，页面会提示先添加邮箱地址。建议先完成 邮箱地址，并设置默认地址。","frontmatter":{"title":"邮箱：撰写邮件 | Product / Mail | Documentation","description":"邮箱：撰写邮件 in Kooboo: 如果进入撰写页时没有可用发件地址，页面会提示先添加邮箱地址。建议先完成 邮箱地址，并设置默认地址。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/mail/compose.html"}]]},"headers":[],"relativePath":"zh/product/mail/compose.md","filePath":"product/mail/compose.md","lastUpdated":1780999973000}'),l={name:"zh/product/mail/compose.md"};function i(n,t,s,b,m,p){const e=r("DocImage");return o(),h("div",null,[t[0]||(t[0]=d('<h1 id="邮箱-撰写邮件" tabindex="-1">邮箱：撰写邮件 <a class="header-anchor" href="#邮箱-撰写邮件" aria-label="Permalink to &quot;邮箱：撰写邮件&quot;">​</a></h1><blockquote><p>撰写页用于新建邮件、回复、全部回复、转发、再次编辑和继续编辑草稿。页面会自动保存草稿，并在离开时提示未保存改动。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>邮箱</strong> -&gt; 左侧 <strong>写邮件</strong></td></tr><tr><td>深链</td><td><code>/_Admin/kmail/compose</code></td></tr><tr><td>前端路由</td><td><code>/kmail/compose</code></td></tr><tr><td>进入方式</td><td>新建、草稿、回复、全部回复、转发、再次编辑</td></tr></tbody></table><p>如果进入撰写页时没有可用发件地址，页面会提示先添加邮箱地址。建议先完成 <a href="./addresses.html">邮箱地址</a>，并设置默认地址。</p>',5)),c(e,{src:"/product/mail/compose-editor.png",alt:"邮箱撰写页：发件人、收件人、附件和富文本编辑器",width:"1120"}),t[1]||(t[1]=d('<h2 id="表单字段" tabindex="-1">表单字段 <a class="header-anchor" href="#表单字段" aria-label="Permalink to &quot;表单字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>发件人</td><td>从当前账号可用邮箱地址中选择；默认取默认地址或第一个地址</td></tr><tr><td>收件人</td><td>输入一个或多个邮箱地址</td></tr><tr><td>抄送 / 密送</td><td>点击 <code>Add Cc</code> / <code>Add Bcc</code> 后显示，可删除</td></tr><tr><td>主题</td><td>必填；空主题不能发送</td></tr><tr><td>附件</td><td>点击 <code>Select</code> 上传文件</td></tr><tr><td>内容</td><td>使用富文本编辑器编写正文</td></tr></tbody></table><p>收件人、抄送和密送使用同一套邮箱校验。已输入的地址标签支持在 <code>To</code>、<code>Cc</code>、<code>Bcc</code> 之间拖动。</p><h2 id="附件" tabindex="-1">附件 <a class="header-anchor" href="#附件" aria-label="Permalink to &quot;附件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>单次选择</td><td>每次选择一个文件</td></tr><tr><td>总大小</td><td>当前邮件全部附件合计不能超过 20 MB</td></tr><tr><td>删除附件</td><td>点击附件标签上的关闭按钮</td></tr><tr><td>发送前上传</td><td>选择文件后会先上传附件，邮件正文只引用上传后的附件信息</td></tr></tbody></table><h2 id="底部按钮" tabindex="-1">底部按钮 <a class="header-anchor" href="#底部按钮" aria-label="Permalink to &quot;底部按钮&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按钮</th><th>说明</th></tr></thead><tbody><tr><td><code>Send</code></td><td>校验表单并发送邮件</td></tr><tr><td><code>Save Draft</code></td><td>手动保存草稿</td></tr><tr><td><code>Cancel</code></td><td>取消当前编辑；若有改动会出现离开确认</td></tr></tbody></table><p>页面每 20 秒检查一次内容变化并自动保存草稿。自动保存过程中，发送按钮会显示“草稿保存中”并暂时不可点击。</p><h2 id="签名" tabindex="-1">签名 <a class="header-anchor" href="#签名" aria-label="Permalink to &quot;签名&quot;">​</a></h2><p>切换发件人时，撰写页会读取该地址的签名并插入正文。签名在 <a href="./addresses.html#签名">邮箱地址</a> 中维护。</p><table tabindex="0"><thead><tr><th>场景</th><th>插入位置</th></tr></thead><tbody><tr><td>新邮件</td><td>正文末尾</td></tr><tr><td>回复 / 转发 / 全部回复</td><td>原邮件内容之前</td></tr><tr><td>发件人切换</td><td>重新读取对应地址签名</td></tr></tbody></table><h2 id="回复、转发和再次编辑" tabindex="-1">回复、转发和再次编辑 <a class="header-anchor" href="#回复、转发和再次编辑" aria-label="Permalink to &quot;回复、转发和再次编辑&quot;">​</a></h2><p>从邮件详情进入撰写页时，路由会带上 <code>sourceId</code> 和 <code>type</code>：</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>Reply</code></td><td>回复发件人</td></tr><tr><td><code>ReplyAll</code></td><td>回复所有相关收件人</td></tr><tr><td><code>Forward</code></td><td>转发当前邮件</td></tr><tr><td><code>Drafts</code></td><td>继续编辑草稿</td></tr><tr><td><code>EditAgain</code></td><td>基于已发送邮件再次编辑</td></tr></tbody></table><p>这些入口会预填发件人、收件人、主题、正文和附件上下文。保存后的草稿会更新当前草稿 ID。</p><h2 id="扩展抽屉" tabindex="-1">扩展抽屉 <a class="header-anchor" href="#扩展抽屉" aria-label="Permalink to &quot;扩展抽屉&quot;">​</a></h2><p>撰写页右侧可能出现邮件扩展抽屉。它来自已启用的邮件扩展模块，用于在写信时提供额外动作或上下文。如何开发模块请从 <a href="./modules.html">邮件扩展模块</a> 进入，脚本 API 细节看 <a href="/kb-docs/zh/api/mail/">k.mail</a>。</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>发送新邮件</td><td>写邮件 -&gt; 选择发件人 -&gt; 填收件人和主题 -&gt; 写正文 -&gt; 发送</td></tr><tr><td>加附件发送</td><td>写邮件 -&gt; 选择附件 -&gt; 等附件标签出现 -&gt; 发送</td></tr><tr><td>继续草稿</td><td>草稿 -&gt; 打开邮件 -&gt; 修改内容 -&gt; 发送或保存</td></tr><tr><td>复用已发邮件</td><td>已发送 -&gt; 打开详情 -&gt; 再次编辑 -&gt; 修改收件人与正文 -&gt; 发送</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./messages.html">邮件列表</a></td><td>从列表进入回复、转发和草稿</td></tr><tr><td><a href="./addresses.html">邮箱地址</a></td><td>发件地址、默认地址和签名</td></tr><tr><td><a href="/kb-docs/zh/api/mail/">k.mail</a></td><td>服务端发信 API</td></tr></tbody></table>',21))])}const f=a(l,[["render",i]]);export{_ as __pageData,f as default};
